select cr_task_submit.*, cr_task.mission_id mission_hash
,cr_task.user_id submit_user,cr_role.`name` submit_user_role,cr_task.role_id submit_user_role_id
from cr_eval_task_submit,cr_task,cr_role

    cr_task_submit.task_id=cr_task.resource_id and cr_task.role_id=cr_role.resource_id
    and cr_task.room_id = #{listQuery.roomId}

        and cr_task.user_id = #{listQuery.studentHash}



        and cr_task_submit.evaluate_status = #{listQuery.evaluateStatus}
